 "content": "from collections import Counter, defaultdict


def transform(grid):
    """Restore erased cells in a framed diagonal-periodic color field."""
    h, w = len(grid), len(grid[0])
    samples = [(r + c, grid[r][c])
               for r in range(3, h) for c in range(3, w)
               if grid[r][c] != 0]

    # Find the shortest diagonal period that explains nearly all visible
    # interior cells. A small tolerance absorbs a few exceptional cells near
    # the pattern's upper-left corner.
    fits = []
    for period in range(1, min(13, h + w)):
        counts = [Counter() for _ in range(period)]
        for diagonal, color in samples:
            counts[diagonal % period][color] += 1
        errors = sum(sum(bucket.values()) - max(bucket.values(), default=0)
                     for bucket in counts)
        fits.append((errors, period, counts))
    best_error = min(item[0] for item in fits)
    tolerance = max(2, len(samples) * 0.02)
    errors, period, counts = min(
        (item for item in fits if item[0] <= best_error + tolerance),
        key=lambda item: item[1])
    colors = [bucket.most_common(1)[0][0] if bucket else 0 for bucket in counts]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = colors[(r + c) % period]
    return out
